import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, interpolate } from '../remotionShim';


export type DynamicFallingDotsProps = Record<string, any>;

const DynamicFallingDots: React.FC<DynamicFallingDotsProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 10,
  dotColor1 = "#FF3366",
  dotColor2 = "#33CCFF",
  dotColor3 = "#FFCC00",
  dotColor4 = "#00FF66",
  dotCount = 120,
  minDotSize = 8,
  maxDotSize = 60,
  swayAmount = 150,
  baseSpeed = 8,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate deterministic particles based on props
  const particles = useMemo(() => {
    const colors = [dotColor1, dotColor2, dotColor3, dotColor4];
    
    return Array.from({ length: dotCount }).map((_, i) => {
      // Map random values deterministically using the index as a seed
      const size = minDotSize + random(`size-${i}`) * (maxDotSize - minDotSize);
      
      const colorIndex = Math.floor(random(`color-${i}`) * colors.length);
      const color = colors[colorIndex % colors.length];
      
      // Start X randomly across the screen
      const startX = random(`x-${i}`) * width;
      
      // Speed multiplier for variety (some fall 2x faster, some slower)
      const speedMultiplier = 0.4 + random(`speed-${i}`) * 1.6;
      // Normalize speed based on 1080p reference height so it scales gracefully
      const speed = baseSpeed * speedMultiplier * (height / 1920); 
      
      // Initial vertical offset so they are distributed uniformly from the start
      const offsetY = random(`offsetY-${i}`) * (height + size * 2);
      
      // Gentle sway parameters
      const swayFreq = 0.005 + random(`freq-${i}`) * 0.02; 
      const swayAmp = swayAmount * (0.2 + random(`amp-${i}`) * 0.8);
      const swayOffset = random(`swayOffset-${i}`) * Math.PI * 2;
      
      // Simulated depth: smaller dots are further away (less opaque)
      const baseOpacity = 0.2 + ((size - minDotSize) / (maxDotSize - minDotSize)) * 0.8; 
      
      return {
        id: i,
        size,
        color,
        startX,
        speed,
        offsetY,
        swayFreq,
        swayAmp,
        swayOffset,
        baseOpacity,
      };
    });
  }, [
    dotCount, 
    minDotSize, 
    maxDotSize, 
    width, 
    height, 
    dotColor1, 
    dotColor2, 
    dotColor3, 
    dotColor4, 
    baseSpeed, 
    swayAmount
  ]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {particles.map((p) => {
        // Total travel distance before wrapping (canvas height + fully offscreen top/bottom)
        const totalTravel = height + p.size * 2;
        
        // Continuous falling logic using modulo wrapping
        const rawY = frame * p.speed + p.offsetY;
        const y = (rawY % totalTravel) - p.size;
        
        // Horizontal sway oscillation
        const x = p.startX + Math.sin(frame * p.swayFreq + p.swayOffset) * p.swayAmp;
        
        return (
          <div
            key={p.id}
            style={{
              position: "absolute",
              width: p.size,
              height: p.size,
              backgroundColor: p.color,
              borderRadius: "50%",
              opacity: p.baseOpacity,
              transform: `translate(${x}px, ${y}px)`,
              transition: "none",
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

export default DynamicFallingDots;